package com.careerpilot.assessment;

import com.careerpilot.modules.assessment.entity.*;import com.careerpilot.modules.assessment.repository.*;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:assessment;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=create-drop","spring.flyway.enabled=false"})@AutoConfigureMockMvc@ActiveProfiles("test")
class AssessmentFlowIntegrationTest{
 static final UUID ASSESSMENT=UUID.fromString("90000000-0000-0000-0000-000000000001"),FULL=UUID.fromString("20000000-0000-0000-0000-000000000005");@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired AssessmentRepository assessments;@Autowired AssessmentAttemptRepository attempts;
 @BeforeEach void seed(){if(!assessments.existsById(ASSESSMENT)){Assessment a=new Assessment();a.setId(ASSESSMENT);a.setTitle("Backend Test");a.setDescription("Deterministic integration assessment");a.setAssessmentType(AssessmentType.ROLE_BASED_MCQ);a.setTargetRole("Backend Developer");a.setDifficulty(AssessmentDifficulty.MEDIUM);a.setDurationMinutes(20);a.setTotalQuestions(10);a.setPassingPercentage(67);a.setGenerationSource("TEST");a.setActive(true);for(int i=1;i<=15;i++)question(a,UUID.fromString("91000000-0000-0000-0000-"+String.format("%012d",i)),i,"Question "+i,"Skill "+((i-1)%4+1),AssessmentDifficulty.values()[(i-1)%3],String.valueOf((char)('A'+(i-1)%4)));assessments.save(a);}if(!assessments.existsById(FULL))seedFullPlacementMock();}
 @Test void catalogStartSubmitTenQuestionsAndProtectOwnership()throws Exception{String owner=register("assessment-owner@example.com"),other=register("assessment-other@example.com");mvc.perform(get("/api/v1/assessments").header("Authorization",owner)).andExpect(status().isOk()).andExpect(jsonPath("$[0].totalQuestions").value(10));String detail=mvc.perform(get("/api/v1/assessments/{id}",ASSESSMENT).header("Authorization",owner)).andExpect(status().isOk()).andExpect(jsonPath("$.questions.length()").value(15)).andReturn().getResponse().getContentAsString();assertHidden(detail);JsonNode started=start(owner);String id=started.path("id").asText();assertHidden(started.toString());String body=submission(started,7,2);mvc.perform(get("/api/v1/assessment-attempts/{id}",id).header("Authorization",other)).andExpect(status().isNotFound());mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",id).header("Authorization",owner).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("SUBMITTED")).andExpect(jsonPath("$.scorePercentage").value(70)).andExpect(jsonPath("$.correctAnswers").value(7)).andExpect(jsonPath("$.incorrectAnswers").value(2)).andExpect(jsonPath("$.unanswered").value(1)).andExpect(jsonPath("$.results.length()").value(10)).andExpect(jsonPath("$.results[0].explanation").exists()).andExpect(jsonPath("$.scoreBySkill").isArray()).andExpect(jsonPath("$.scoreByDifficulty.length()").value(3));mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",id).header("Authorization",owner).contentType("application/json").content(body)).andExpect(status().isConflict());mvc.perform(get("/api/v1/assessment-attempts").header("Authorization",owner)).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").value(id));mvc.perform(get("/api/v1/assessment-attempts/latest").header("Authorization",owner)).andExpect(status().isOk()).andExpect(jsonPath("$.scorePercentage").value(70));}
 @Test void selectionIsUniquePersistedAcrossRefreshAndIndependentPerAttempt()throws Exception{String owner=register("assessment-selection@example.com");JsonNode first=start(owner),second=start(owner);List<String>firstIds=ids(first),secondIds=ids(second);assertThat(firstIds).hasSize(10).doesNotHaveDuplicates();assertThat(secondIds).hasSize(10).doesNotHaveDuplicates();JsonNode refreshed=json.readTree(mvc.perform(get("/api/v1/assessment-attempts/{id}",first.path("id").asText()).header("Authorization",owner)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());assertThat(ids(refreshed)).containsExactlyElementsOf(firstIds);assertThat(first.path("id").asText()).isNotEqualTo(second.path("id").asText());assertThat(first.path("questions").path(0).path("order").asInt()).isEqualTo(1);assertThat(second.path("questions").path(0).path("order").asInt()).isEqualTo(1);}
 @Test void rejectsInvalidDuplicateAndUnknownQuestions()throws Exception{String owner=register("assessment-invalid@example.com");JsonNode started=start(owner);String id=started.path("id").asText(),questionId=started.path("questions").path(0).path("id").asText();String invalid=json.writeValueAsString(Map.of("answers",List.of(Map.of("questionId",questionId,"selectedOptionKey","Z"))));mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",id).header("Authorization",owner).contentType("application/json").content(invalid)).andExpect(status().isBadRequest());String duplicate=json.writeValueAsString(Map.of("answers",List.of(Map.of("questionId",questionId,"selectedOptionKey","A"),Map.of("questionId",questionId,"selectedOptionKey","B"))));mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",id).header("Authorization",owner).contentType("application/json").content(duplicate)).andExpect(status().isBadRequest());String unknown=json.writeValueAsString(Map.of("answers",List.of(Map.of("questionId",UUID.randomUUID(),"selectedOptionKey","A"))));mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",id).header("Authorization",owner).contentType("application/json").content(unknown)).andExpect(status().isBadRequest());}
 @Test void serverExpiresAttemptAndRejectsSubmission()throws Exception{String owner=register("assessment-expiry@example.com");UUID id=UUID.fromString(start(owner).path("id").asText());AssessmentAttempt attempt=attempts.findById(id).orElseThrow();attempt.setStartedAt(Instant.now().minus(Duration.ofHours(1)));attempts.save(attempt);mvc.perform(get("/api/v1/assessment-attempts/{id}",id).header("Authorization",owner)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("EXPIRED")).andExpect(jsonPath("$.questions.length()").value(0));mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",id).header("Authorization",owner).contentType("application/json").content("{\"answers\":[]}" )).andExpect(status().isConflict());}
 @Test void zeroCorrectAnswersDoNotClaimAStrongestTopic()throws Exception{String owner=register("assessment-zero@example.com");JsonNode started=start(owner);String response=mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",started.path("id").asText()).header("Authorization",owner).contentType("application/json").content(submission(started,0,10))).andExpect(status().isOk()).andExpect(jsonPath("$.scorePercentage").value(0)).andExpect(jsonPath("$.correctAnswers").value(0)).andExpect(jsonPath("$.incorrectAnswers").value(10)).andReturn().getResponse().getContentAsString();JsonNode result=json.readTree(response);assertThat(result.path("strongestTopic").isNull()).isTrue();assertThat(result.path("weakestTopic").isTextual()).isTrue();}
 @Test void fullPlacementMockUsesExactSectionQuotasAndPersistsSelection()throws Exception{String owner=register("assessment-full-mock@example.com");JsonNode started=json.readTree(mvc.perform(post("/api/v1/assessments/{id}/attempts",FULL).header("Authorization",owner)).andExpect(status().isCreated()).andExpect(jsonPath("$.questions.length()").value(20)).andReturn().getResponse().getContentAsString());Map<String,Long>counts=new HashMap<>();started.path("questions").forEach(q->counts.merge(q.path("skillTag").asText(),1L,Long::sum));assertThat(counts).containsEntry("APTITUDE",4L).containsEntry("LOGICAL",3L).containsEntry("PROGRAMMING",3L).containsEntry("DSA",3L).containsEntry("DBMS_SQL",2L).containsEntry("CS_FUNDAMENTALS",2L).containsEntry("DEBUGGING",2L).containsEntry("BACKEND",1L);List<String>original=ids(started);JsonNode refreshed=json.readTree(mvc.perform(get("/api/v1/assessment-attempts/{id}",started.path("id").asText()).header("Authorization",owner)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());assertThat(ids(refreshed)).containsExactlyElementsOf(original).doesNotHaveDuplicates();assertHidden(started.toString());}
 private JsonNode start(String auth)throws Exception{return json.readTree(mvc.perform(post("/api/v1/assessments/{id}/attempts",ASSESSMENT).header("Authorization",auth)).andExpect(status().isCreated()).andExpect(jsonPath("$.questions.length()").value(10)).andReturn().getResponse().getContentAsString());}
 private String submission(JsonNode started,int correctCount,int incorrectCount)throws Exception{List<Map<String,String>>answers=new ArrayList<>();for(int i=0;i<correctCount+incorrectCount;i++){JsonNode question=started.path("questions").path(i);String id=question.path("id").asText();int number=Integer.parseInt(question.path("text").asText().replace("Question ",""));String correct=String.valueOf((char)('A'+(number-1)%4)),selected=i<correctCount?correct:correct.equals("A")?"B":"A";answers.add(Map.of("questionId",id,"selectedOptionKey",selected));}return json.writeValueAsString(Map.of("answers",answers));}
 private List<String>ids(JsonNode attempt){List<String>ids=new ArrayList<>();attempt.path("questions").forEach(q->ids.add(q.path("id").asText()));return ids;}
 private void assertHidden(String value){assertThat(value).doesNotContain("isCorrect").doesNotContain("correctOption").doesNotContain("Explanation for");}
 private void question(Assessment a,UUID id,int order,String text,String skill,AssessmentDifficulty difficulty,String correct){AssessmentQuestion q=new AssessmentQuestion();q.setId(id);q.setAssessment(a);q.setQuestionOrder(order);q.setQuestionType(QuestionType.MCQ);q.setQuestionText(text);q.setExplanation("Explanation for "+text);q.setDifficulty(difficulty);q.setSkillTag(skill);for(String key:List.of("A","B","C","D")){AssessmentOption o=new AssessmentOption();o.setQuestion(q);o.setOptionKey(key);o.setOptionText(key+" option");o.setCorrect(key.equals(correct));q.getOptions().add(o);}a.getQuestions().add(q);}
 private void seedFullPlacementMock(){Assessment a=new Assessment();a.setId(FULL);a.setTitle("Full Company Placement Mock Test");a.setDescription("Balanced selection test");a.setAssessmentType(AssessmentType.ROLE_BASED_MCQ);a.setDifficulty(AssessmentDifficulty.HARD);a.setDurationMinutes(30);a.setTotalQuestions(20);a.setPassingPercentage(60);a.setGenerationSource("TEST");a.setCatalogGroup("PLACEMENT_MOCK");a.setActive(true);Map<String,Integer>sizes=new LinkedHashMap<>();sizes.put("APTITUDE",8);sizes.put("LOGICAL",6);sizes.put("PROGRAMMING",6);sizes.put("DSA",6);sizes.put("DBMS_SQL",4);sizes.put("CS_FUNDAMENTALS",4);sizes.put("DEBUGGING",4);sizes.put("BACKEND",2);int order=1;for(var entry:sizes.entrySet())for(int i=0;i<entry.getValue();i++){AssessmentQuestion q=new AssessmentQuestion();q.setId(UUID.nameUUIDFromBytes(("full-"+order).getBytes()));q.setAssessment(a);q.setQuestionOrder(order);q.setQuestionType(QuestionType.MCQ);q.setQuestionText(entry.getKey()+" question "+i);q.setExplanation("Server-only explanation");q.setDifficulty(AssessmentDifficulty.MEDIUM);q.setSkillTag(entry.getKey());q.setSelectionCategory(entry.getKey());for(String key:List.of("A","B","C","D")){AssessmentOption o=new AssessmentOption();o.setQuestion(q);o.setOptionKey(key);o.setOptionText(key+" option");o.setCorrect(key.equals("A"));q.getOptions().add(o);}a.getQuestions().add(q);order++;}assessments.save(a);}
 private String register(String email)throws Exception{String body=json.writeValueAsString(Map.of("fullName","Assessment Test","email",email,"password","Password1","confirmPassword","Password1"));JsonNode response=json.readTree(mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(body)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());return"Bearer "+response.path("accessToken").asText();}
}
